import {H3} from '@jetbrains/ring-ui-built/components/heading/heading'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import {memo, Suspense, useMemo} from 'react'
import {EntryPointContainer, graphql, useFragment} from 'react-relay'
import type {PreloadedEntryPoint} from 'react-relay/relay-hooks/EntryPointTypes'

import useDocumentTitle from '../../../../../../hooks/useDocumentTitle'
import type {AgentTypeId} from '../../../../../../types'
import Loader from '../../../../../common/Loader/Loader'
import PageTitle from '../../../../../common/PageTitle/PageTitle'
import type {AgentTypeParametersComponentType} from '../../../../AgentsPages/AgentTypePage/AgentTypeParameters/AgentTypeParameters'
import AgentParametersHelp from '../../components/Help/AgentParametersHelp'

import type {AgentTypePipelinePage_agentType$key} from './__generated__/AgentTypePipelinePage_agentType.graphql'
import AgentTypeJobList from './JobList/AgentTypeJobList'

import styles from './AgentTypePipelinePage.module.css'

import LinuxIcon from 'src/svg/os-linux.svg'
import MacOSIcon from 'src/svg/os-mac.svg'
import WindowsIcon from 'src/svg/os-windows.svg'

const fragment = graphql`
  fragment AgentTypePipelinePage_agentType on AgentTypeRest {
    name
    environment {
      osType
      osName
    }
  }
`

type Props = {
  agentTypeId: AgentTypeId
  agentTypeKey: AgentTypePipelinePage_agentType$key | null
  parametersEntryPoint?: PreloadedEntryPoint<AgentTypeParametersComponentType>
}

function AgentTypePipelinePage({agentTypeId, agentTypeKey, parametersEntryPoint}: Props) {
  const agentType = useFragment(fragment, agentTypeKey)
  useDocumentTitle(agentType && `Agent Summary (${agentType.name}) — TeamCity Pipelines`)

  const icon = useMemo(() => {
    switch (agentType?.environment?.osType) {
      case 'Linux':
        return LinuxIcon
      case 'macOS':
        return MacOSIcon
      case 'Windows':
        return WindowsIcon
      default:
        return 'unknown-os'
    }
  }, [agentType?.environment?.osType])

  return (
    <div data-test={'agent-type'} className={styles.page}>
      <PageTitle className={styles.title}>
        {icon && <SvgIcon className={styles.icon} icon={icon} />}
        {agentType?.name}
      </PageTitle>
      <div className={styles.description}>{agentType?.environment?.osName}</div>
      <AgentTypeJobList agentTypeId={agentTypeId} />
      <H3 className={styles.parametersTitle}>
        {'Agent Parameters'}
        <AgentParametersHelp />
      </H3>
      {parametersEntryPoint && (
        <Suspense fallback={<Loader />}>
          <EntryPointContainer entryPointReference={parametersEntryPoint} props={{}} />
        </Suspense>
      )}
    </div>
  )
}

export default memo(AgentTypePipelinePage)
