import {HTTPCodesEnum} from '@jetbrains/teamcity-ui/dist/services'
import type {EntryPointProps} from 'react-relay'
import {usePreloadedQuery} from 'react-relay'
import {useParams} from 'react-router'

import {toAgentTypeId} from '../../../../../types'

import type {AgentTypePipelinePageQuery} from './__generated__/AgentTypePipelinePageQuery.graphql'
import {query} from './AgentTypePipelinePage.queries'
import AgentTypePipelinePage from './Page/AgentTypePipelinePage'

import {useCanViewAgentDetails} from 'src/components/pages/AgentsPages/AgentsPages.hooks'
import type {AgentTypeParametersEntryPoint} from 'src/components/pages/AgentsPages/AgentTypePage/AgentTypeParameters/AgentTypeParameters.entryPoint'

const FORBIDDEN_ERROR = {statusCode: HTTPCodesEnum.FORBIDDEN, message: ''}

type Params = {
  agentTypeId: string
}
type Queries = {main: AgentTypePipelinePageQuery}
export type NestedEntryPoints = {parameters: typeof AgentTypeParametersEntryPoint}
export default function AgentTypePipelinePageContainer({
  queries,
  entryPoints,
}: EntryPointProps<Queries, NestedEntryPoints, {}, {}>) {
  const params = useParams<Params>()
  const agentTypeId = toAgentTypeId(params.agentTypeId ?? '')
  const data = usePreloadedQuery(query, queries.main)
  const canViewAgentDetails = useCanViewAgentDetails(data)

  if (!canViewAgentDetails) {
    throw FORBIDDEN_ERROR
  }

  return (
    <AgentTypePipelinePage
      agentTypeKey={data.agentType ?? null}
      key={params.agentTypeId}
      agentTypeId={agentTypeId}
      parametersEntryPoint={entryPoints.parameters}
    />
  )
}
export type AgentTypePipelinePageContainerComponent = typeof AgentTypePipelinePageContainer
