import {createSelector} from 'reselect'

import type {State} from '../../../../../../../reducers/types'
import {getAllAgentPreviews} from '../../../../../../../selectors'
import type {AgentTypeId} from '../../../../../../../types'
import {getAgentIdListByAgentType} from '../../../../../AgentsPages/AgentsPages.selectors'

export const agentListSelector = () =>
  createSelector(
    getAllAgentPreviews,
    getAgentIdListByAgentType,
    (_: State, props: {agentTypeId: AgentTypeId}) => props.agentTypeId,
    (allAgents, agentIdList, agentTypeId) => {
      const agentList = agentIdList[agentTypeId]
      return agentList
        ?.map(agentId => allAgents[agentId])
        .filter(agent => agent?.build)
        .map(agent => agent?.build!)
    },
  )
