import {memo, useMemo} from 'react'

import JobList from '../../../JobList/JobList'

import {agentListSelector} from './AgentTypeJobTile.selectors'

import {useAppSelector} from 'src/hooks/react-redux'

interface Props {
  agentTypeId: number
}

function AgentTypeJobList(props: Props) {
  const {agentTypeId} = props

  const selector = useMemo(() => agentListSelector(), [])
  const buildIds = useAppSelector(state =>
    selector(state, {
      agentTypeId,
    }),
  )

  return buildIds && <JobList buildIds={buildIds} />
}

export default memo(AgentTypeJobList)
